package filemanager

import "github.com/washsky/mygpt-test/internal/ui"

const filePage = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>文件管理 · mygpt-test</title>
<style>
:root{color-scheme:light;--ink:#20332e;--muted:#687b74;--accent:#18785d;--line:#dce6e0}*{box-sizing:border-box}body{margin:0;background:#f4f7f4;color:var(--ink);font:15px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1120px;margin:32px auto;padding:0 24px}header,.heading,.actions,.pager{display:flex;align-items:center;justify-content:space-between;gap:12px}nav,.actions{display:flex;gap:10px;flex-wrap:wrap}h1{font-size:32px;margin:12px 0 0}h2{font-size:19px;margin:0}p{color:var(--muted)}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}.eyebrow{font-size:12px;letter-spacing:2px;color:var(--accent);font-weight:700}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;margin:20px 0}.sub{margin:4px 0 20px}.muted,.meta{color:var(--muted);font-size:13px}label{display:grid;gap:6px;font-size:13px;color:var(--muted)}input,select,button,.action{font:inherit;border:1px solid var(--line);border-radius:9px;min-height:42px;padding:8px 12px;background:white;color:var(--ink)}input,select{width:100%;min-width:0}button,.action{cursor:pointer}button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:disabled{opacity:.5;cursor:default}:focus-visible{outline:3px solid #76bca4;outline-offset:3px}.drop{border:2px dashed #b7cfc1;border-radius:12px;padding:22px;background:#f7faf7;text-align:center}.drop.over{background:#e5f4eb;border-color:var(--accent)}.drop input{max-width:420px;background:white;margin:12px auto 0}.upload-bottom{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:14px}.association{display:grid;grid-template-columns:1fr 2fr;gap:12px;margin:14px 0}.toolbar{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;margin:20px 0}.item{display:grid;grid-template-columns:48px minmax(0,1fr) auto;align-items:center;gap:14px;padding:18px 0;border-bottom:1px solid var(--line)}.badge{border-radius:10px;background:#edf3ee;color:var(--accent);font-size:11px;font-weight:700;text-align:center;padding:12px 3px}.name{font-weight:650;overflow-wrap:anywhere}.meta{overflow-wrap:anywhere}.danger{color:#a63c39}.empty{text-align:center;padding:44px 12px;color:var(--muted)}.notice{white-space:pre-wrap;overflow-wrap:anywhere;margin-top:12px}.notice:empty{display:none}progress{width:100%;accent-color:var(--accent);margin-top:12px}.pager{margin-top:20px}.settings{padding:16px 24px}.settings summary{cursor:pointer;color:var(--muted)}.token-row{display:flex;gap:12px;align-items:end;margin-top:14px}.token-row label{flex:1}.queue{font-size:13px;color:var(--muted);overflow-wrap:anywhere;margin-top:10px}.queue:empty{display:none}[hidden]{display:none!important}@media(max-width:650px){main{padding:0 16px;margin:20px auto}header{align-items:start}h1{font-size:27px}.card{padding:18px}.toolbar{grid-template-columns:1fr 1fr}.toolbar label:first-child{grid-column:1/-1}.item{grid-template-columns:40px minmax(0,1fr);gap:10px}.item .actions{grid-column:2;justify-content:flex-start}.upload-bottom,.token-row{align-items:stretch;flex-direction:column}.association{grid-template-columns:1fr}.pager{flex-wrap:wrap}nav{justify-content:flex-end}}
</style>` + ui.Head + `</head><body>` + ui.Nav + `<main>
<div class="workspace-hero"><div><div class="eyebrow">资料库</div><h1>文件资料</h1><p>让每份文件都有来处，随时回到相关笔记。</p></div><a class="workspace-link" href="/#compose">＋ 写笔记</a></div><div id="file-context" class="context-banner" hidden></div>
<p class="sub">把资料放在一起，需要时轻松找到。</p>
<section class="card" aria-labelledby="upload-title"><h2 id="upload-title">上传文件</h2><p class="muted">支持多选或拖拽，每个文件最大 20 MB。</p>
<form id="upload"><div class="drop" id="drop"><label for="file">将文件拖到这里，或选择文件<input id="file" type="file" multiple></label><div id="queue" class="queue"></div></div>
<div class="upload-bottom"><details><summary>关联到帖子或回复（可选）</summary><div class="association"><label>关联类型<select id="related-type"><option value="">暂不关联</option><option value="post">帖子</option><option value="reply">回复</option></select></label><label>记录 ID<input id="related-id" maxlength="128" placeholder="输入已有帖子或回复 ID"></label></div></details><button class="primary" id="submit" type="submit" disabled>开始上传</button></div></form>
<progress id="progress" max="100" value="0" hidden aria-label="当前文件上传进度"></progress><div id="notice" class="notice" role="status"></div></section>
<section class="card" aria-labelledby="files-title"><div class="heading"><div><h2 id="files-title">我的文件</h2><span id="summary" class="muted"></span></div><button id="refresh" type="button">刷新</button></div>
<div class="toolbar"><label>搜索文件<input id="search" type="search" placeholder="输入文件名…"></label><label>文件类型<select id="kind"><option value="">全部类型</option><option value="image">图片</option><option value="document">文档与文本</option><option value="archive">压缩包</option><option value="other">其他</option></select></label><label>排序<select id="sort"><option value="new">最近上传</option><option value="old">最早上传</option><option value="name">文件名称</option><option value="size">文件从大到小</option></select></label></div>
<div id="list" aria-live="polite"><div class="empty">正在加载文件…</div></div><div class="pager"><span id="count" class="muted"></span><div class="actions"><button id="prev" type="button">上一页</button><span id="page"></span><button id="next" type="button">下一页</button></div></div></section>
<details class="card settings" id="settings"><summary>管理设置 · 删除文件时使用</summary><div class="token-row"><label>管理员令牌<input id="admin-token" type="password" autocomplete="off" placeholder="输入管理员令牌"></label><button id="save-token" type="button">保存到本次会话</button><button id="clear-token" type="button">清除</button></div><div id="token-notice" class="notice" role="status"></div></details>
</main><script>
const $=id=>document.getElementById(id);
const context=new URLSearchParams(location.search),contextType=context.get("related_type"),contextID=context.get("related_id");const linkedContext=["post","reply"].includes(contextType)&&!!contextID;
let files=[],selected=[],page=1,busy=false,requestID=0;const pageSize=20;
try{$('admin-token').value=sessionStorage.getItem('forum-admin-token')||''}catch(_){}
$('save-token').onclick=()=>{try{sessionStorage.setItem('forum-admin-token',$('admin-token').value.trim());$('token-notice').textContent='已保存到本次浏览器会话。'}catch(_){$('token-notice').textContent='浏览器无法保存会话，当前页面仍可使用。'}};
$('clear-token').onclick=()=>{$('admin-token').value='';try{sessionStorage.removeItem('forum-admin-token')}catch(_){}$('token-notice').textContent='已清除令牌。'};
const sizeText=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';
const extension=f=>(f.name.split('.').length>1?f.name.split('.').pop():'').toLowerCase();
function kind(f){const ext=extension(f);if(/^(png|jpe?g|gif|webp|bmp|svg|ico)$/.test(ext))return 'image';if(/^(pdf|txt|md|log|json|csv|docx?|xlsx?|pptx?|odt|rtf)$/.test(ext))return 'document';if(/^(zip|rar|7z|gz|tar|bz2|xz)$/.test(ext))return 'archive';return 'other'}
function node(tag,cls,text){const el=document.createElement(tag);el.className=cls;el.textContent=text;return el}
function render(){const q=$('search').value.trim().toLocaleLowerCase();let result=files.filter(f=>(!linkedContext||(f.association?.type===contextType&&f.association?.id===contextID))&&f.name.toLocaleLowerCase().includes(q)&&(!$('kind').value||kind(f)===$('kind').value));result.sort((a,b)=>{switch($('sort').value){case 'old':return Date.parse(a.uploaded_at)-Date.parse(b.uploaded_at);case 'name':return a.name.localeCompare(b.name,'zh-CN',{numeric:true});case 'size':return b.size-a.size;default:return Date.parse(b.uploaded_at)-Date.parse(a.uploaded_at)}});const pages=Math.max(1,Math.ceil(result.length/pageSize));page=Math.min(page,pages);$('summary').textContent=files.length+' 个文件 · '+sizeText(files.reduce((n,f)=>n+f.size,0));$('list').replaceChildren();if(!result.length)$('list').append(node('div','empty',files.length?'没有找到匹配文件，试试其他关键词或类型。':'还没有文件，上传第一份资料吧。'));for(const f of result.slice((page-1)*pageSize,page*pageSize)){const row=node('div','item',''),info=node('div','',''),actions=node('div','actions','');info.append(node('div','name',f.name),node('div','meta',sizeText(f.size)+' · '+new Date(f.uploaded_at).toLocaleString()+(f.association?.type?' · '+(f.association.type==='post'?'帖子':'回复')+' '+f.association.id:'')));for(const [label,suffix] of [['预览','/preview'],['下载','']]){const a=node('a','action',label);a.href=suffix?'/files/view/'+encodeURIComponent(f.id):'/api/files/'+encodeURIComponent(f.id);if(suffix){a.target='_blank';a.rel='noopener'}actions.append(a)}if(f.association?.id&&['post','reply'].includes(f.association.type)){const source=node('a','action','查看来源');source.href='/#'+f.association.type+'/'+encodeURIComponent(f.association.id);actions.append(source)}if(window.workspaceOptions.enable_clipboard){const share=node('button','action','发送到共享');share.type='button';share.onclick=async()=>{share.disabled=true;const ok=await window.workspaceShareFile?.(f);$('notice').textContent=ok?'附件已加入共享历史。':'发送失败，请确认共享剪贴板已开启。';share.disabled=false};actions.append(share)}const remove=node('button','danger','移入回收站');remove.type='button';remove.onclick=async()=>{const token=$('admin-token').value.trim();if(!token){$('settings').open=true;$('admin-token').focus();$('token-notice').textContent='请先输入管理员令牌，再删除文件。';return}if(!confirm('将“'+f.name+'”移入回收站？可以在回收站恢复。'))return;remove.disabled=true;try{const r=await fetch('/api/files/'+encodeURIComponent(f.id),{method:'DELETE',headers:{'X-Admin-Token':token}});if(!r.ok)throw Error(r.status===403?'管理员令牌无效，请检查管理设置。':'删除失败，请稍后重试。');files=files.filter(x=>x.id!==f.id);render();$('notice').textContent='已将“'+f.name+'”移入回收站。'}catch(e){$('notice').textContent=e.message;remove.disabled=false}};actions.append(remove);window.workspaceCompactActions(actions,1);row.append(node('div','badge',(extension(f)||'FILE').slice(0,5).toUpperCase()),info,actions);$('list').append(row)}$('count').textContent='共 '+result.length+' 个匹配文件';$('page').textContent=page+' / '+pages;$('prev').disabled=page===1;$('next').disabled=page===pages}
async function refresh(){const id=++requestID;$('refresh').disabled=true;try{const r=await fetch('/api/files');if(!r.ok)throw Error('文件列表加载失败，请点击刷新重试。');const data=await r.json();if(id!==requestID)return;files=data.items;render()}catch(e){if(id===requestID)$('list').replaceChildren(node('div','empty',e.message))}finally{if(id===requestID)$('refresh').disabled=false}}
for(const id of ['search','kind','sort'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;render()});$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('refresh').onclick=refresh;
function select(items){if(busy)return;selected=Array.from(items);$('queue').textContent=selected.length?'已选择 '+selected.length+' 个文件：'+selected.map(f=>f.name).join('、'):'';$('submit').disabled=!selected.length;$('submit').textContent='上传'+(selected.length?' '+selected.length+' 个文件':'文件')}
$('file').onchange=e=>select(e.target.files);for(const event of ['dragenter','dragover'])$('drop').addEventListener(event,e=>{e.preventDefault();if(!busy)$('drop').classList.add('over')});for(const event of ['dragleave','drop'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.remove('over')});$('drop').addEventListener('drop',e=>select(e.dataTransfer.files));
function upload(file,type,id){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest(),data=new FormData();data.append('file',file);data.append('related_type',type);data.append('related_id',id);xhr.open('POST','/api/files');if(window.workspaceOptions.enable_network_resilience)xhr.timeout=300000;xhr.ontimeout=()=>reject(Error('上传超时，结果尚未确认，请刷新列表后再重试')); xhr.upload.onprogress=e=>{if(e.lengthComputable)$('progress').value=Math.round(e.loaded/e.total*100)};xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve():reject(Error(xhr.responseText||'服务器未能完成上传'));xhr.onerror=()=>reject(Error('网络异常，上传结果未知，请刷新列表确认后再重试'));xhr.send(data)})}
$('upload').onsubmit=async e=>{e.preventDefault();if(busy||!selected.length)return;const type=$('related-type').value,id=$('related-id').value.trim();if(type&&!id){$('notice').textContent='请填写关联记录 ID。';$('related-id').focus();return}if(!type&&id){$('notice').textContent='请先选择关联类型，或清空记录 ID。';return}busy=true;for(const el of $('upload').elements)el.disabled=true;$('progress').hidden=false;const failed=[],errors=[];let success=0;try{for(let i=0;i<selected.length;i++){const f=selected[i];$('notice').textContent='正在上传 '+(i+1)+' / '+selected.length+'：'+f.name;$('progress').value=0;try{if(!f.size)throw Error('空文件无法上传');if(f.size>20*1024*1024)throw Error('超过 20 MB 上限');await upload(f,type,id);success++}catch(err){failed.push(f);errors.push(f.name+'：'+err.message)}}}finally{busy=false;for(const el of $('upload').elements)el.disabled=false;$('progress').hidden=true;$('file').value='';select(failed);$('notice').textContent='上传完成：'+success+' 个成功'+(failed.length?'，'+failed.length+' 个失败。失败文件已保留，可重试。\n'+errors.join('\n'):'。');await refresh()}};
if(linkedContext){$('related-type').value=contextType;$('related-id').value=contextID;$('related-type').closest('details').open=true;const banner=$('file-context');banner.hidden=false;banner.append(node('span','','当前仅显示这条'+(contextType==='post'?'笔记':'回复')+'直接关联的附件；新上传文件会自动关联。 '));const back=node('a','workspace-link','返回来源');back.href='/#'+contextType+'/'+encodeURIComponent(contextID);const all=node('a','workspace-link','查看全部文件');all.href='/files';banner.append(back,all)}
window.addEventListener('workspace-options',()=>render());window.addEventListener('workspace-change',event=>{if(!event.detail.path||event.detail.path.startsWith('/api/files')||event.detail.path.startsWith('/api/forum/')){if(busy)return;refresh()}});
refresh();
</script>` + ui.Foot + `</body></html>`
